bool UartInstruments::show(CWnd* owner,const std::wstring& ini){if(!GetSafeHwnd()){ini_=ini;if(!Create(IDD_UART_INSTRUMENTS,owner))return false;}ShowWindow(SW_SHOW);SetForegroundWindow();choices();update();return true;}
BOOL UartInstruments::OnInitDialog(){CDialog::OnInitDialog();known_.clear();font_=make_ui_font(m_hWnd,std::wstring(AfxGetApp()->m_lpCmdLine).find(L"--font125")!=std::wstring::npos);const auto child=[&](const wchar_t* cls,const wchar_t* title,DWORD style,int id){return ::CreateWindowW(cls,title,WS_CHILD|WS_VISIBLE|style,0,0,1,1,m_hWnd,reinterpret_cast<HMENU>(static_cast<INT_PTR>(id)),nullptr,nullptr);};
    for(size_t n=0;n<5;++n){picks_[n]=child(L"COMBOBOX",L"",WS_TABSTOP|CBS_DROPDOWN|CBS_AUTOHSCROLL|WS_VSCROLL,6000+static_cast<int>(n));::SendMessageW(picks_[n],CB_LIMITTEXT,1024,0);wchar_t value[4096]{};GetPrivateProfileStringW(L"Instruments",(L"Key"+std::to_wstring(n)).c_str(),L"",value,4096,ini_.c_str());std::string decoded;if(uart_unhex(message_utf8(value),decoded)&&!decoded.empty()){try{::SetWindowTextW(picks_[n],uart_wide(decoded).c_str());}catch(...){}}}
    for(const auto h:picks_){const auto saved=text(h);::SendMessageW(h,CB_ADDSTRING,0,reinterpret_cast<LPARAM>(L"(none)"));::SetWindowTextW(h,saved.empty()?L"(none)":saved.c_str());}
    settings_=child(L"BUTTON",L"Ranges / FFT...",WS_TABSTOP|BS_PUSHBUTTON,6010);analyze_=child(L"BUTTON",L"Analyze FFT",WS_TABSTOP|BS_PUSHBUTTON,6011);automatic_=child(L"BUTTON",L"Auto FFT (2/s)",WS_TABSTOP|BS_AUTOCHECKBOX,6012);hint_=child(L"STATIC",L"Number / Gauge / Bar / LED (top, left to right). Independent channel choices; FFT below. Display projections only; capture/export values stay raw.",SS_NOPREFIX,0);
    const auto cls=AfxRegisterWndClass(0,LoadCursorW(nullptr,IDC_ARROW),GetSysColorBrush(COLOR_3DFACE));canvas_.CreateEx(0,cls,L"Instruments",WS_CHILD|WS_VISIBLE,CRect(0,0,1,1),this,6020);canvas_.draw=[this](CDC& dc,CRect r){draw(dc,r);};
    wchar_t saved[1024]{};GetPrivateProfileStringW(L"Instruments",L"Ranges",L"",saved,1024,ini_.c_str());std::wistringstream input(saved);wchar_t comma=0;double a=0,b=100,c=0,d=100,e=0.5,f=0;size_t p=256;if(input>>a>>comma&&comma==L','&&input>>b>>comma&&comma==L','&&input>>c>>comma&&comma==L','&&input>>d>>comma&&comma==L','&&input>>e>>comma&&comma==L','&&input>>f>>comma&&comma==L','&&input>>p){if(std::isfinite(a)&&std::isfinite(b)&&std::isfinite(c)&&std::isfinite(d)&&std::isfinite(e)&&std::isfinite(f)&&a<b&&c<d&&f>=0&&f<=1e9&&p>=32&&p<=4096&&!(p&(p-1))){gauge_low_=a;gauge_high_=b;bar_low_=c;bar_high_=d;led_=e;rate_=f;points_=p;}else fft_status_=L"Invalid saved ranges; review Ranges / FFT before using these defaults.";}
    ::EnumChildWindows(m_hWnd,[](HWND h,LPARAM f)->BOOL{::SendMessageW(h,WM_SETFONT,static_cast<WPARAM>(f),FALSE);return TRUE;},reinterpret_cast<LPARAM>(font_));ready_=true;SetWindowPos(nullptr,70,40,1100,850,SWP_NOZORDER);SetTimer(1,500,nullptr);layout();return TRUE;}
std::string UartInstruments::key(size_t n)const{const auto s=text(picks_[n]);return s==L"(none)"?std::string{}:message_utf8(s);}
void UartInstruments::choices(){if(!ready_||!keys_)return;const auto next=keys_();if(next==known_)return;known_=next;for(const auto h:picks_){const auto saved=text(h);::SendMessageW(h,CB_RESETCONTENT,0,0);::SendMessageW(h,CB_ADDSTRING,0,reinterpret_cast<LPARAM>(L"(none)"));for(const auto& k:known_){const auto label=uart_wide(k);::SendMessageW(h,CB_ADDSTRING,0,reinterpret_cast<LPARAM>(label.c_str()));}::SetWindowTextW(h,saved.empty()?L"(none)":saved.c_str());}}
void UartInstruments::persist(size_t n){const auto encoded=uart_wide(uart_hex(key(n)));if(!WritePrivateProfileStringW(L"Instruments",(L"Key"+std::to_wstring(n)).c_str(),encoded.c_str(),ini_.c_str()))fft_status_=L"Cannot save instrument channel; use a writable tool folder.";}
void UartInstruments::update(bool fft){if(!ready_||!series_)return;choices();for(size_t n=0;n<4;++n){const auto samples=key(n).empty()?std::vector<std::pair<double,double>>{}:series_(key(n),1);valid_[n]=!samples.empty()&&std::isfinite(samples.back().second);if(valid_[n])values_[n]=samples.back().second;}
    if(fft){const auto selected=key(4);const auto samples=selected.empty()?std::vector<std::pair<double,double>>{}:series_(selected,points_);std::string error;Spectrum result;if(signal_fft(samples,points_,rate_,result,error)){spectrum_=std::move(result);fft_status_=L"Hann / mean removed | "+std::to_wstring(points_)+L" points | fs "+number(spectrum_.sample_rate)+L" Hz | peak "+number(spectrum_.peak_hz)+L" Hz, amplitude "+number(spectrum_.peak_amplitude)+L" | "+uart_wide(spectrum_.provenance);}else{spectrum_={};fft_status_=uart_wide(error);}}
    canvas_.Invalidate(FALSE);}
void UartInstruments::draw(CDC& dc,CRect r){const auto old=dc.SelectObject(CFont::FromHandle(font_?font_:reinterpret_cast<HFONT>(GetStockObject(DEFAULT_GUI_FONT))));dc.SetBkMode(TRANSPARENT);dc.SetTextColor(GetSysColor(COLOR_WINDOWTEXT));const int gap=10,tile_h=std::min(240,r.Height()/2),tile_w=(r.Width()-gap*3)/4;const wchar_t* titles[]={L"Number",L"Gauge",L"Bar",L"LED"};
    const auto label=[&](const std::wstring& s,CRect box,UINT flags=DT_LEFT|DT_WORDBREAK){dc.DrawTextW(s.c_str(),static_cast<int>(s.size()),&box,flags|DT_NOPREFIX);};
    for(size_t n=0;n<4;++n){CRect tile(static_cast<int>(n)*(tile_w+gap),0,static_cast<int>(n)*(tile_w+gap)+tile_w,tile_h);dc.FillSolidRect(tile,RGB(250,250,250));dc.DrawEdge(tile,EDGE_ETCHED,BF_RECT);auto inside=tile;inside.DeflateRect(10,10);label(titles[n],CRect(inside.left,inside.top,inside.right,inside.top+24));label(valid_[n]?number(values_[n]):L"n/a",CRect(inside.left,inside.top+30,inside.right,inside.top+58));if(!valid_[n])continue;
        const auto y=inside.top+80;if(n==1){const double ratio=std::clamp((values_[n]-gauge_low_)/(gauge_high_-gauge_low_),0.0,1.0);CRect gauge(inside.left,y,inside.right,std::min(inside.bottom-25,y+100));const int cx=(gauge.left+gauge.right)/2,cy=gauge.bottom,rad=std::max(10,std::min(gauge.Width()/2,gauge.Height()));dc.MoveTo(cx-rad,cy);for(unsigned point=1;point<=64;++point){const double a=3.141592653589793*(1-point/64.0);dc.LineTo(cx+static_cast<int>(rad*std::cos(a)),cy-static_cast<int>(rad*std::sin(a)));}const double angle=3.141592653589793*(1-ratio);dc.MoveTo(cx,cy);dc.LineTo(cx+static_cast<int>(rad*std::cos(angle)),cy-static_cast<int>(rad*std::sin(angle)));label(number(gauge_low_)+L" .. "+number(gauge_high_),CRect(inside.left,inside.bottom-24,inside.right,inside.bottom));}
        else if(n==2){const auto ratio=std::clamp((values_[n]-bar_low_)/(bar_high_-bar_low_),0.0,1.0);CRect bar(inside.left,y,inside.right,y+28);dc.DrawEdge(bar,EDGE_SUNKEN,BF_RECT);bar.DeflateRect(3,3);bar.right=bar.left+static_cast<int>(bar.Width()*ratio);dc.FillSolidRect(bar,RGB(65,65,65));label(number(bar_low_)+L" .. "+number(bar_high_),CRect(inside.left,y+36,inside.right,inside.bottom));}
        else if(n==3){const bool on=values_[n]>=led_;CBrush brush(on?RGB(65,65,65):RGB(220,220,220));const auto previous=dc.SelectObject(&brush);dc.Ellipse(inside.left,y,inside.left+50,y+50);dc.SelectObject(previous);label(std::wstring(on?L"ON":L"OFF")+L" (>= "+number(led_)+L")",CRect(inside.left,y+60,inside.right,inside.bottom));}}
    CRect fft(r.left,tile_h+gap,r.right,r.bottom);dc.FillSolidRect(fft,RGB(250,250,250));dc.DrawEdge(fft,EDGE_ETCHED,BF_RECT);label(fft_status_,CRect(fft.left+10,fft.top+8,fft.right-10,fft.top+65));CRect plot(fft.left+70,fft.top+80,fft.right-25,fft.bottom-38);if(plot.Width()>0&&plot.Height()>0){dc.Rectangle(plot);if(!spectrum_.bins.empty()){const double ymax=std::max(1e-12,spectrum_.peak_amplitude*1.1),xmax=spectrum_.sample_rate/2;bool first=true;for(const auto& p:spectrum_.bins){const auto x=plot.left+static_cast<int>(plot.Width()*p.first/xmax),y=plot.bottom-static_cast<int>(plot.Height()*std::min(1.0,p.second/ymax));if(first){dc.MoveTo(x,y);first=false;}else dc.LineTo(x,y);}label(number(ymax),CRect(fft.left+4,plot.top-8,plot.left-4,plot.top+18));label(L"0",CRect(fft.left+4,plot.bottom-16,plot.left-4,plot.bottom+8));label(L"0 Hz",CRect(plot.left,plot.bottom+10,plot.left+90,plot.bottom+32));label(number(xmax)+L" Hz",CRect(plot.right-120,plot.bottom+10,plot.right+15,plot.bottom+32),DT_RIGHT|DT_SINGLELINE);}}
    dc.SelectObject(old);}
void UartInstruments::settings(){const auto convert=[](const std::vector<std::wstring>& f,std::array<double,7>& v,std::wstring& error){for(size_t n=0;n<v.size();++n)if(!uart_number(f[n],n==5?0:n==6?32:-1e100,n==5?1e9:n==6?4096:1e100,v[n])){error=L"Invalid finite range, threshold, sample rate or point count.";return false;}const auto p=static_cast<size_t>(v[6]);if(v[0]>=v[1]||v[2]>=v[3]||v[6]!=p||(p&(p-1))){error=L"Min must be below max; FFT points must be a power of two, 32..4096.";return false;}return true;};
    UartToolForm form(L"Instrument ranges / FFT",L"FFT is a one-sided Hann-windowed amplitude spectrum with the mean removed. Sample rate 0 validates original sample timestamps within 5%; repeated/backward/bursty clocks are rejected. Enter a known device sample rate only when that assumption is justified. No silent resampling. Gauges clamp the drawing, while the actual number remains visible.",{{L"Gauge minimum",number(gauge_low_)},{L"Gauge maximum",number(gauge_high_)},{L"Bar minimum",number(bar_low_)},{L"Bar maximum",number(bar_high_)},{L"LED ON at or above",number(led_)},{L"Sample rate Hz (0=clocks)",number(rate_)},{L"FFT points",std::to_wstring(points_)}},{},[convert](const auto& f,std::wstring& e){std::array<double,7> v{};return convert(f,v,e);},this);if(form.DoModal()!=IDOK)return;std::array<double,7> v{};std::wstring error;if(!convert(form.values(),v,error))return;std::wstring encoded;for(const auto& s:form.values()){if(!encoded.empty())encoded+=L",";encoded+=s;}if(!WritePrivateProfileStringW(L"Instruments",L"Ranges",encoded.c_str(),ini_.c_str())){fft_status_=L"Cannot save ranges; previous settings retained.";return;}gauge_low_=v[0];gauge_high_=v[1];bar_low_=v[2];bar_high_=v[3];led_=v[4];rate_=v[5];points_=static_cast<size_t>(v[6]);spectrum_={};update(::SendMessageW(automatic_,BM_GETCHECK,0,0)==BST_CHECKED);}
BOOL UartInstruments::OnCommand(WPARAM w,LPARAM l){const auto id=LOWORD(w);if(id>=6000&&id<6005&&(HIWORD(w)==CBN_SELCHANGE||HIWORD(w)==CBN_KILLFOCUS)){persist(id-6000);if(id==6004){spectrum_={};fft_status_=L"Select Analyze FFT for this channel, or enable Auto FFT.";}update();return TRUE;}if(HIWORD(w)==BN_CLICKED){if(id==6010){settings();return TRUE;}if(id==6011){update(true);return TRUE;}if(id==6012){update(::SendMessageW(automatic_,BM_GETCHECK,0,0)==BST_CHECKED);return TRUE;}}return CDialog::OnCommand(w,l);}
void UartInstruments::OnTimer(UINT_PTR){if(IsWindowVisible())update(::SendMessageW(automatic_,BM_GETCHECK,0,0)==BST_CHECKED);}
void UartInstruments::layout(){if(!ready_)return;CRect r;GetClientRect(&r);HDC dc=::GetDC(m_hWnd);const auto old=SelectObject(dc,font_);TEXTMETRICW tm{};GetTextMetricsW(dc,&tm);SelectObject(dc,old);::ReleaseDC(m_hWnd,dc);const int row=std::max<int>(28,tm.tmHeight+12),gap=8,width=(r.Width()-20-gap*3)/4;for(size_t n=0;n<4;++n)::MoveWindow(picks_[n],10+static_cast<int>(n)*(width+gap),10,width,row*8,TRUE);::MoveWindow(hint_,10,row+16,r.Width()-20,row*2,TRUE);int y=row*3+24;::MoveWindow(picks_[4],10,y,std::max(160,r.Width()-600),row*8,TRUE);int x=std::max(178,r.Width()-582);::MoveWindow(settings_,x,y,160,row,TRUE);::MoveWindow(analyze_,x+168,y,150,row,TRUE);::MoveWindow(automatic_,x+326,y,240,row,TRUE);canvas_.MoveWindow(10,y+row+10,r.Width()-20,std::max(120,r.Height()-y-row-20));}
void UartInstruments::OnSize(UINT t,int w,int h){CDialog::OnSize(t,w,h);if(t!=SIZE_MINIMIZED)layout();}
void UartInstruments::OnGetMinMaxInfo(MINMAXINFO* i){CDialog::OnGetMinMaxInfo(i);i->ptMinTrackSize.x=960;i->ptMinTrackSize.y=700;}
LRESULT UartInstruments::OnDpiChanged(WPARAM,LPARAM l){const auto next=make_ui_font(m_hWnd);if(next){const auto old=font_;font_=next;::EnumChildWindows(m_hWnd,[](HWND h,LPARAM f)->BOOL{::SendMessageW(h,WM_SETFONT,static_cast<WPARAM>(f),FALSE);return TRUE;},reinterpret_cast<LPARAM>(font_));if(old)DeleteObject(old);}if(l){const auto r=reinterpret_cast<const RECT*>(l);SetWindowPos(nullptr,r->left,r->top,r->right-r->left,r->bottom-r->top,SWP_NOZORDER|SWP_NOACTIVATE);}layout();canvas_.Invalidate(FALSE);return 0;}
void UartInstruments::OnDestroy(){ready_=false;KillTimer(1);for(auto h=::GetWindow(m_hWnd,GW_CHILD);h;){const auto next=::GetWindow(h,GW_HWNDNEXT);::DestroyWindow(h);h=next;}CDialog::OnDestroy();if(font_){DeleteObject(font_);font_=nullptr;}}
